void parse_pdf_object(struct pdf_struct *pdf, struct pdf_obj *obj) {
    // Check the size of the object and locate the start of its dictionary
    size_t obj_size = obj->size;
    const char *dict_start = find_dict_start(pdf, obj_size);

    if (!dict_start) {
        return; // Dictionary not found
    }

    // Locate the end of the dictionary and parse it
    const char *dict_end = find_dict_end(pdf, dict_start, obj_size);
    if (!dict_end) {
        return; // Malformed dictionary
    }

    // Process names within the dictionary and normalize them
    std::map<std::string, std::string> name_map;
    process_names(pdf, dict_start, dict_end, name_map);

    // Handle states such as linearization and actions
    if (check_linearization(pdf, dict_start, dict_end)) {
        obj->flags |= PDF_OBJ_FLAG_LINEARIZED;
    }

    if (check_actions(pdf, dict_start, dict_end)) {
        obj->flags |= PDF_OBJ_FLAG_ACTION;
    }

    // Check for filters and update the object's filter count
    int filter_count = count_filters(pdf, dict_start, dict_end);
    obj->filter_count = filter_count;

    if (filter_count > 0) {
        obj->flags |= PDF_OBJ_FLAG_FILTERED;
    }

    // Log object flags for debugging
    log_flags(obj->flags);
}

void parse_pdf_object(struct pdf_struct *pdf, struct pdf_obj *obj) {
    int dict_start = find_dict_start(pdf, obj);
    int dict_end = find_dict_end(pdf, obj);
    char *normalized_name = nullptr;

    for (int i = dict_start; i < dict_end; ++i) {
        if (is_name(pdf->data[i])) {
            normalized_name = normalize_name(pdf->data + i);
            add_name_to_object(obj, normalized_name);
            free(normalized_name);
        }
    }

    if (is_linearized(pdf, obj)) {
        obj->flags.linearized = true;
    }

    if (has_action(pdf, obj)) {
        obj->flags.has_action = true;
    }

    int filter_count = count_filters(pdf, obj);
    if (filter_count > 0) {
        obj->flags.filtered = true;
        obj->filter_count = filter_count;
    }

    log_object_flags(obj);
}
